func ParseGetOpenAPIDescriptionResponse(rsp *http.Response) (response *GetOpenAPIDescriptionResponse, err error) {
	defer func() {
		if err != nil {
			err = &ResponseError{StatusCode: rsp.StatusCode, Err: err}
		}
	}()
	bodyBytes, err := io.ReadAll(rsp.Body)
	defer func() { _ = rsp.Body.Close() }()
	if err != nil {
		return nil, err
	}

	response = &GetOpenAPIDescriptionResponse{
		Body:         bodyBytes,
		HTTPResponse: rsp,
	}

	if rsp.StatusCode == http.StatusOK && strings.Contains(rsp.Header.Get("Content-Type"), "yaml") {
		description := string(bodyBytes)
		response.YAML200 = &description
		return response, nil
	}

	switch {
	case strings.Contains(rsp.Header.Get("Content-Type"), "yaml") && rsp.StatusCode == 200:
		var dest string
		if err := yaml.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.YAML200 = &dest

	case strings.Contains(rsp.Header.Get("Content-Type"), "json") && true:
		var dest UnexpectedError
		if err := json.Unmarshal(bodyBytes, &dest); err != nil {
			return nil, err
		}
		response.ApplicationproblemJSONDefault = &dest

	}

	return response, nil
}

